    describe("933393 - Plain paste at the end of the line creates empty para issue resolved", () => {
        let rteObj: RichTextEditor;
        beforeAll((done: Function) => {
            rteObj = renderRTE({
                value: `<p><b>Description:</b></p><p class="custom">The Rich Text Editor (RTE) control is an easy to render in client side.</p>`,
                pasteCleanupSettings: {
                    prompt: true
                }
            });
            done();
        });
        it("Empty para should not be created when pasting ", (done) => {
            const clipBoardData: string = `To analyze, optimize, and enhance the readability of the insert logic, excluding pasteHTML and insertHTML`;
            const dataTransfer: DataTransfer = new DataTransfer();
            dataTransfer.setData('text/plain', clipBoardData);
            const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
            rteObj.pasteCleanupSettings.prompt = false;
            rteObj.pasteCleanupSettings.plainText = true;
            rteObj.pasteCleanupSettings.deniedTags = [];
            rteObj.pasteCleanupSettings.deniedAttrs = [];
            rteObj.pasteCleanupSettings.allowedStyleProps = [];
            rteObj.dataBind();
            let focusNode: Node = (rteObj as any).inputElement.querySelector('.custom').childNodes[0]
            rteObj.formatter.editorManager.nodeSelection.setSelectionText(document, focusNode, focusNode, 71, 71);
            rteObj.onPaste(pasteEvent);
            setTimeout(() => {
                let pastedElm: any = (rteObj as any).inputElement.innerHTML;
                let expected: boolean = true;
                let expectedElem: string = `<p><b>Description:</b></p><p class="custom">The Rich Text Editor (RTE) control is an easy to render in client side.To analyze, optimize, and enhance the readability of the insert logic, excluding&nbsp;pasteHTML&nbsp;and&nbsp;insertHTML</p>`;
                if (pastedElm !== expectedElem) {
                    expected = false;
                }
                expect(expected).toBe(true);
                expect(rteObj.inputElement.querySelectorAll('p:empty').length === 0).toBe(true);
                done();
            }, 100);
        });
 
        afterAll((done: DoneFn) => {
            destroy(rteObj);
            done();
        });
    });

    describe('Should remove <br> element while pasting', () => {
        let editorInstance: RichTextEditor;
        const clipboardHtml: string = `
            <p style="text-align: left;">
                <span style="color: rgb(66, 66, 66); font-family: 'Segoe UI', sans-serif; font-size: 15px; font-style: normal; font-weight: 400; text-align: left; text-indent: 0px; text-transform: none; white-space: normal; background-color: rgb(255, 255, 255); float: none; display: inline !important;">
                    After copy and pasting some contents into the Editor, pressing Shift + Enter key creates two new lines into the RichTextEditor. Need to resolve this issue
                </span>
            </p>`;
        beforeAll(() => {
            editorInstance = renderRTE({
                value: `<p id="start"><br></p>`
            });
        });
        afterAll(() => {
            destroy(editorInstance);
        });
        it('should paste content without <br> inside an empty <p>', (done: DoneFn) => {
            const startElement: HTMLElement | null = document.getElementById('start');
            const selection = new NodeSelection();
            if (startElement) {
                selection.setCursorPoint(document, startElement, 0);
            }
            const dataTransfer = new DataTransfer();
            dataTransfer.setData('text/html', clipboardHtml);
            const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
            editorInstance.onPaste(pasteEvent);
            setTimeout(() => {
                expect(editorInstance.inputElement.innerHTML).not.toContain('<br>');
                done();
            }, 100);
        });
    });

    describe('Should not merge inline span with existing anchor during paste', () => {
        let rteObj: RichTextEditor;
        const clipboardHtml: string = `<span style="font-size: 15px;">This is a paragraph.</span>`;
        beforeAll(() => {
            rteObj = renderRTE({
                value: `<p><a href="https://www.syncfusion.com/" id="start">Syncfusion</a></p>`
            });
        });
        afterAll(() => {
            destroy(rteObj);
        });
        it('should paste span content outside the existing anchor', (done: DoneFn) => {
            const anchor: HTMLElement = document.getElementById('start');
            const selection = new NodeSelection();
            if (anchor && anchor.firstChild) {
                selection.setCursorPoint(document, anchor.firstChild as Element, (anchor.firstChild as Element).textContent.length);
            }
            const dataTransfer = new DataTransfer();
            dataTransfer.setData('text/html', clipboardHtml);
            const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', {
                clipboardData: dataTransfer
            } as ClipboardEventInit);
            rteObj.onPaste(pasteEvent);
            const pastedElm: string = (rteObj as any).inputElement.innerHTML;
            const expectedElem: string =
                `<p><a href="https://www.syncfusion.com/" id="start">Syncfusion</a><span style="font-size: 15px;">This is a paragraph.</span></p>`;
            const expected: boolean = pastedElm.replace(/\s/g, '') === expectedElem.replace(/\s/g, '');
            expect(expected).toBe(true);
            done();
        });
    });

