            setCursorPoint(rteObj.inputElement.firstElementChild, 0);
            const dataTransfer: DataTransfer = new DataTransfer();
            dataTransfer.setData('text/html', '\x3C!--StartFragment--><b style="font-weight:normal;" id="docs-internal-guid-8660e126-7fff-9dfa-ae81-d3b0033c7d6e"><p dir="ltr" style="line-height:1.38;margin-top:0pt;margin-bottom:0pt;"><span style="font-size:11pt;font-family:Arial,sans-serif;color:#000000;background-color:transparent;font-weight:700;font-style:italic;font-variant:normal;text-decoration:none;vertical-align:baseline;white-space:pre;white-space:pre-wrap;">asdasdasdasd</span></p></b><br class="Apple-interchange-newline">\x3C!--EndFragment-->');
            const pasteEvent: ClipboardEvent = new ClipboardEvent('paste', { clipboardData: dataTransfer } as ClipboardEventInit);
